import{_ as t}from"./chunks/icon.B7gRmRZx.js";import{_ as o,a as s,b as r,c as a,d as n,e as i,f as d,g as p,h as c,i as l,j as h,k as g,l as u}from"./chunks/0.1.12-193-neustart-de.DMY_PLph.js";import{_ as m,o as b,c as f,a3 as k}from"./chunks/framework.BlfGB29P.js";const x=JSON.parse('{"title":"Logic Studio","description":"HA Logic Studio Pro 0.1.84 · Home Assistant startup trigger in Rules","frontmatter":{"title":"Logic Studio","description":"HA Logic Studio Pro 0.1.84 · Home Assistant startup trigger in Rules"},"headers":[],"relativePath":"en/projects/logic-studio/index.md","filePath":"en/projects/logic-studio/index.md","lastUpdated":1794679141000}'),v={name:"en/projects/logic-studio/index.md"};function y(w,e,A,S,H,P){return b(),f("div",null,[...e[0]||(e[0]=[k('<h1 id="logic-studio" tabindex="-1"><img class="package-icon" src="'+t+'" width="40" height="40" alt=""> Logic Studio <a class="header-anchor" href="#logic-studio" aria-label="Permalink to &quot;&lt;img class=&quot;package-icon&quot; src=&quot;/images/logic-studio/icon.svg&quot; width=&quot;40&quot; height=&quot;40&quot; alt=&quot;&quot;&gt; Logic Studio&quot;">​</a></h1><p><strong>0.1.12 – public test update, 8 November 2026.</strong> Both interface and documentation now support <strong>DE/EN/FR</strong>. Logic Studio is a standalone HA app for visual function-block plans, independent of Grafik Visual Studio and Blocks for HA. The React Flow canvas retains custom blocks, typed connections, zoom and MiniMap; libraries and licenses are bundled locally.</p><div class="warning custom-block"><p class="custom-block-title">Test release</p><p>Install on a test system first and create a full backup beforehand. Native detail properties currently use JSON. The app does not write automations/scripts back to HA or control devices. Review and install generated output yourself.</p></div><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/logic-studio-v0.1.12" target="_blank" rel="noreferrer">GitHub test release and ZIP</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/logic_studio" target="_blank" rel="noreferrer">Source in the shared repository</a></p><h2 id="ha-logic-studio-pro" tabindex="-1">HA Logic Studio Pro <a class="header-anchor" href="#ha-logic-studio-pro" aria-label="Permalink to &quot;HA Logic Studio Pro&quot;">​</a></h2><p>HA Logic Studio Pro is a standalone Home Assistant app in the shared UGSo repository. It builds on Logic Studio and draws on experience with ioBroker.</p><p><strong>Available features</strong></p><ul><li><strong>Function block diagram:</strong> Connect blocks, display signals at the inputs, and simulate the diagram. Execution on the HA server can respond to changes or run on a fixed cycle.</li><li><strong>Rules and Blocks A:</strong> Build automations visually and export them as HA YAML.</li><li><strong>Blocks JS, JavaScript, and TypeScript:</strong> Edit logic, test it with simulated values, and run it on the HA server.</li><li><strong>HA YAML:</strong> Edit, validate, and export automations and scripts.</li><li><strong>Project management:</strong> Store projects and folders on the server for each HA user.</li><li><strong>Language selection:</strong> The editors are available in German, English, and French.</li></ul><h3 id="ha-logic-studio-pro-0-1-81–0-1-100" tabindex="-1">HA Logic Studio Pro 0.1.81–0.1.100 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-81–0-1-100" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.81–0.1.100&quot;">​</a></h3><p><strong>0.1.84 · Home Assistant startup trigger in Rules</strong></p><p>The Rules palette and wizard offer <strong>Home Assistant started</strong>. The YAML export uses <code>trigger: homeassistant</code> with <code>event: start</code>.</p><p>In the live test, the automation turned on the test helper after Home Assistant Core restarted. <a href="/en/collection/test-systems#testsystem-pc">PC test system (64-bit)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.84" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.84 · GitHub / ZIP</a></p><p><strong>0.1.83 · MQTT triggers in Rules</strong></p><p>The Rules wizard offers <strong>MQTT message</strong> with a required topic and an optional payload filter. With no filter, any message on the topic triggers the automation.</p><p>In the live test, the automation ran exactly once when both the topic and payload matched. A wrong topic and a different payload produced no runs. The Home Assistant trace confirmed the counter action. <a href="/en/collection/test-systems#testsystem-pc">PC test system (64-bit)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.83" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.83 · GitHub / ZIP</a></p><p><strong>0.1.82</strong></p><p>The Rules wizard offers a <strong>Time from helper</strong> trigger. Select a Home Assistant <code>input_datetime</code> helper that includes a time. The YAML export uses <code>trigger: time</code> and sets <code>at</code> to the entity ID. Home Assistant picks up changes made to the helper’s time.</p><p>In the live test on the PC test system (64-bit), the helper time was changed from 17:27:27 to 17:27:56. The original time passed without a run. The Home Assistant trace confirms the automation ran at <strong>17:27:56</strong>. <a href="/en/collection/test-systems#testsystem-pc">PC test system (64-bit)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.82" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.82 · GitHub / ZIP</a></p><p><strong>0.1.81</strong></p><p>The Rules wizard offers sunrise and sunset triggers. Enter the optional offset in minutes. Negative values trigger before the solar event and positive values trigger after it.</p><p>The YAML export was checked and validated in the installed version on the <a href="/en/collection/test-systems#testsystem-pc">PC test system (64-bit)</a>. For 30 minutes before sunrise, it generated <code>event: sunrise</code> and <code>offset: -1800</code>. For 15 minutes after sunset, it generated <code>event: sunset</code> and <code>offset: 900</code>. The YAML offsets are in seconds.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.81" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.81 · GitHub / ZIP</a></p><h3 id="ha-logic-studio-pro-0-1-61–0-1-80" tabindex="-1">HA Logic Studio Pro 0.1.61–0.1.80 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-61–0-1-80" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.61–0.1.80&quot;">​</a></h3><details class="details custom-block"><summary>Release history</summary><p><strong>0.1.80</strong></p><p>The Rules wizard offers a <strong>Numeric threshold</strong> trigger with an above limit, a below limit, or both limits for a range. The attribute and minimum duration are optional. The YAML export uses Home Assistant’s native <code>numeric_state</code> trigger.</p><p>On the <a href="/en/collection/test-systems#testsystem-pc">PC test system (64-bit)</a>, the installed Rules editor generated <code>above: 50</code> for a threshold of 50. In the live test of the exported YAML, the automation fired once at 51. The counter stayed at 1 at both 65 and 49. It reached 2 when the value crossed the threshold again at 52.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.80" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.80 · GitHub / ZIP</a></p><p><strong>0.1.79</strong></p><p>The Blocks JS import preview shows which Home Assistant entity each block needs or which code change is still required. Fixed ioBroker IDs can be mapped to HA entities directly in the preview.</p><p>Using the original <code>test33.xml</code> export on the <a href="/en/collection/test-systems#testsystem-pc">PC test system (64-bit)</a>, the state trigger was mapped to a sensor and the write block to a number helper. The test run simulated writes of <code>21</code> and <code>20</code>.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.79" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.79 · GitHub / ZIP</a></p><p><strong>0.1.78</strong></p><p>In <strong>Global scripts</strong>, JavaScript and TypeScript projects can select saved scripts from the folder of the same name. The dialog shows how to call named functions exposed with <code>export function</code>, such as <code>shared.script_43.twice(21)</code>.</p><p>On the <a href="/en/collection/test-systems#testsystem-pc">PC (64) test system</a>, one general JavaScript project and one general TypeScript project called the same global TypeScript function. Both returned <code>42</code> in the test run and in the runtime. TypeScript highlighted an argument with the wrong type on line 2. The selection persisted after reloading.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.78" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.78 · GitHub / ZIP</a></p><p><strong>0.1.77</strong></p><p><strong>Check types</strong> checks the TypeScript source and the script API types. The editor highlights lines with errors. Clicking a line number in the log jumps to the original source. Test runs and the runtime check types before executing the script.</p><p>On the <a href="/en/collection/test-systems#testsystem-pc">PC (64) test system</a>, two deliberate type errors were highlighted on lines 2 and 3. After correction, the test run succeeded. Starting the faulty script in the runtime reported line 2.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.77" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.77 · GitHub / ZIP</a></p><p><strong>0.1.76</strong></p><p>In the JavaScript and TypeScript editors, typing <code>ha.</code> suggests script API methods. The list shows parameters and return types. The editor highlights the current parameter while you enter a call.</p><p>The Chrome test on the <a href="/en/collection/test-systems#testsystem-pc">PC (64) test system</a> verified keyboard selection in both editors and the signatures for <code>ha.readState</code>, <code>ha.callAction</code> and <code>ha.pause</code>.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.76" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.76 · GitHub / ZIP</a></p><p><strong>0.1.75</strong></p><p>When a test run or runtime error can be traced to the source, the log shows the original JavaScript or TypeScript line. Clicking the line number jumps to it in the editor.</p><p>On the <strong>PC (64) test system</strong>, both execution modes reported the deliberate errors at <strong>JavaScript line 3</strong> and <strong>TypeScript line 5</strong>. The TypeScript line number was correct even though transpilation removed a type declaration.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.75" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.75 · GitHub / ZIP</a></p><p><strong>0.1.74</strong></p><p>Logic Studio Pro keeps the last 100 runtime log entries per user and project. On the PC (64) test system, an entry remained available with the same timestamp after an app restart. The script was stopped, and the entry did not appear in another project.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.74" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.74 · GitHub / ZIP</a></p><p><strong>0.1.73</strong></p><p>In the runtime test on the PC (64) test system with 0.1.72, the second trigger started before the first had finished. Both completed. A deliberate error stopped the affected script. The other script then successfully handled a third trigger.</p><p>After the local update to 0.1.73 on the PC (64) test system, the Home Assistant app page no longer displayed “Experimental”, and the Studio header no longer displayed “Internal test”. The three test projects were deleted.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.73" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.73 · GitHub / ZIP</a></p><p><strong>0.1.72</strong></p><p>Blocks JS imports ioBroker script messages with replies and computed target addresses. The preview identifies the receiver address and reply handling to review for each affected block.</p><p>On the PC (64) test system, one running Blocks JS script built the target address from two pieces of text. The second script logged receipt, and the sender executed its reply block. Both test projects were then deleted and the temporary permission for <code>logic_studio_script_message</code> was removed.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.72" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.72 · GitHub / ZIP</a></p><p><strong>0.1.71</strong></p><p>The Expert mode toggle in the project menu saves the preference for each Home Assistant user. It reveals advanced tools, including source and scripting API in JavaScript, import and code output in Blocks JS, and diagnostics and execution settings in function block diagrams. Save, Cancel, Test run and Play remain directly accessible in the editors that support them.</p><p>After a full backup on the PC (64) test system, the three editors were checked. The preference persisted after reloading. The original setting was then restored and confirmed after another reload.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.71" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.71 · GitHub / ZIP</a></p><p><strong>0.1.70</strong></p><p>Use the pencil icon in the project tree to rename a custom folder. After a full backup on the PC (64) test system, the project tree exports before renaming and after reloading showed the same folder ID, project assignments and order for both projects. The original folder name was restored and verified after another reload.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.70" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.70 · GitHub / ZIP</a></p><p><strong>0.1.69</strong></p><p>The Rules wizard follows language changes in the open editor. After a full backup on the PC (64) test system, the Chrome tablet viewport (820 × 1180 px) test verified that the title, steps and triggers followed <strong>DE → EN → FR → DE</strong>. Both the Studio interface and the Home Assistant app manager displayed <strong>0.1.69</strong>. The server now reads the displayed version from the package metadata.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.69" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.69 · GitHub / ZIP</a></p><p><strong>0.1.68</strong></p><p>The YAML export downloads the file directly from the editor. Two exports on the PC (64) test system produced two complete, byte-identical YAML files. Chrome flagged the second export as an <strong>insecure download</strong>. After the tester selected <strong>Keep</strong>, the second file was also complete in the Downloads folder.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.68" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.68 · GitHub / ZIP</a></p><p><strong>0.1.67</strong></p><p>Current public test release. Create a full backup and try the update on a test system first.</p><p>The imported “State exists?” and “Object ID” blocks retain their ioBroker IDs. Explicitly map each ID to a Home Assistant entity in its block. Blocks JS also finds embedded Blockly data in JavaScript files when other comments follow it.</p><p>The import preview’s <strong>Required code changes</strong> section explains how to replace unsupported blocks such as <code>exec</code>. After a full backup on the PC (64) test system, XML and JavaScript test files were imported and the new mapping fields were checked in the editor.</p><p><strong>Reconnection after a Core restart</strong></p><p>A full backup was created on the PC (64) test system before the test. After Home Assistant Core restarted, the runtime reconnected 31 seconds after the connection dropped. The same JavaScript run then received the test helper’s change from <code>off</code> to <code>on</code> and the custom HA event <code>logic_studio_runtime_test</code> with its test payload.</p><p><strong>Folder and script order after reloading</strong></p><p>After a full backup on the PC (64) test system, two test scripts were moved to a different folder by drag and drop. After saving the order and reloading Logic Studio Pro, both scripts were still in the destination folder in the saved order.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.67" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.67 · GitHub / ZIP</a></p><p><strong>0.1.66</strong></p><p>Enable <strong>Save counters and latches</strong> in the function block diagram and save the project. CTU, CTD, CTUD, RS and SR can restore their values after an app restart.</p><p>The Blocks JS import report lists calculated ioBroker IDs separately. Use the imported block’s <strong>ID mapping (JSON)</strong> field to map each possible ioBroker ID to a Home Assistant entity.</p><p>On the PC (64) test system, the CTU counter and RS latch retained <code>1</code> and <code>true</code> after an app restart.</p><p>In the live test on the PC (64) test system, the imported Blocks JS script calculated the ioBroker ID <code>zigbee.0.sensor</code>. It used <strong>ID mapping (JSON)</strong> to read the Home Assistant test helper <code>input_boolean.logic_studio_runtime_test</code>. Two runs started with <strong>Play</strong> logged <code>false</code> with the helper off and <code>true</code> with it on.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.66" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.66 · GitHub / ZIP</a></p><p><strong>0.1.65</strong></p><p><strong>Autostart, simulation and ioBroker import</strong></p><p>JavaScript, TypeScript and function block diagrams can run when the app starts. Enable <strong>Run when the app starts</strong> and save the project. The simulation supports breakpoints and single stepping. Automatic layout preserves pinned blocks. The Blocks JS ioBroker import preview lists unsupported blocks and fixed IDs to map.</p><p>On the PC (64) test system, the saved JavaScript test project started automatically after an app restart. A simulation breakpoint and single step were also checked, as was the ioBroker import preview with a fixed ID.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.65" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.65 · GitHub / ZIP</a></p><p><strong>Expanded Rules and live test on the PC (64) test system</strong></p><p>State triggers support from and to values, an attribute and a minimum duration. Conditions check states, attributes and numeric limits. THEN and ELSE support a Home Assistant action picker with JSON parameters and separate delay steps.</p><p>The editor and action picker were tested locally in the browser. After a full backup, the generated YAML ran directly in Home Assistant on the PC (64) test system. A brief pulse did not trigger a run. Holding the state for three seconds ran THEN. A change to the display name ran ELSE. Both traces confirmed a two-second delay and the expected text value. The test automation and both helpers were removed.</p><p>The new blocks export as HA YAML. Rules → JS reports when a block prevents conversion.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.62" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.62 · GitHub / ZIP</a></p><p><strong>YAML export and live test on the PC (64) test system</strong></p><p>The Rules exporter preserves states such as <code>on</code> and <code>off</code> as strings instead of YAML booleans. The corrected automation ran directly in Home Assistant on the PC (64) test system using test helpers.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Trigger</th><th>Condition</th><th>Home Assistant trace result</th></tr></thead><tbody><tr><td>State change</td><td>OR matched</td><td>Both THEN actions</td></tr><tr><td>State change</td><td>AND did not match</td><td>Both ELSE actions</td></tr><tr><td>HA event</td><td>NOT matched</td><td>Both THEN actions</td></tr><tr><td>Time 20:26</td><td>NOT did not match</td><td>Both ELSE actions</td></tr></tbody></table></div><p>A full backup was taken before testing. The test automation and all three helpers were removed afterwards.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.61" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.61 · GitHub / ZIP</a></p></details><h3 id="ha-logic-studio-pro-0-1-41–0-1-60" tabindex="-1">HA Logic Studio Pro 0.1.41–0.1.60 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-41–0-1-60" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.41–0.1.60&quot;">​</a></h3><details class="details custom-block"><summary>Release history</summary><p><strong>Rules: compact palette and multiple triggers</strong></p><p>The editor has a compact icon list on the left. A rule can combine state changes, a daily time and Home Assistant events. Conditions support AND, OR and NOT. Both THEN and ELSE run multiple actions in the order shown.</p><p>On the PC (64) test system, an existing rule was tested with three triggers, two conditions and two actions per branch. The YAML preview showed the expected structure. In the Studio test run, all three simulated triggers ran both THEN actions when the OR condition was met. When the AND condition was not met, both ELSE actions ran in the configured order. No real devices were operated.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.60" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.60 · GitHub / ZIP</a></p><p><img src="'+o+'" alt="Rules editor on the PC (64) test system with a compact palette and both action branches"></p><p><strong>Create rules with the wizard</strong></p><p>Select <strong>Rules → Wizard</strong>. It takes you through <strong>Trigger → Conditions → Actions → Review</strong>. A rule can react to a state change, a daily time in the HA time zone, or a Home Assistant event. Conditions and the ELSE branch are optional. Review shows the YAML preview. <strong>Apply</strong> transfers the draft to the editor; <strong>Save</strong> persists it. Existing rules can still be edited and opened as JavaScript or HA YAML.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.59" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.59 · GitHub / ZIP</a></p><p>On 12 November 2026, all three triggers were tested directly in Home Assistant on the PC (64) test system. A state change from off to on, the daily trigger at 19:38 (HA local time), and the <code>rules_live_0159_event</code> event each switched the test output on. A full backup was created before testing. The three test automations and both test helpers were removed afterward.</p><p><img src="'+s+`" alt="Home Assistant shows the last run of all three Rules test automations and the test output switched on"></p><p><strong>Changes since 0.1.12</strong></p><ul><li><strong>Project tree and editors:</strong> Projects and folders are stored on the server per HA user. Existing browser projects can be migrated on first launch from the original browser. JavaScript and TypeScript have syntax highlighting, line numbers and their own toolbars. The project picker, tree and filters use matching icons and colors. Blocks A and Blocks JS have separate filters. The automatic project pane width can still be adjusted with the handle.</li><li><strong>Blocks A and Blocks JS:</strong> Blocks A uses the bundled Blocks for HA catalog. Blocks JS has its own JavaScript palette. Blocks A exports HA automations as YAML. Blocks JS generates JavaScript for the test run and runtime. Unrecognized ioBroker blocks are retained as placeholders and prevent code generation until replaced. Map ioBroker object IDs to Home Assistant entity IDs.</li><li><strong>Function block diagram:</strong> Simulation, one-second step and reset have icons in the top toolbar. Output format and preview sit on the right. Connections can be moved to another target input, and signal values appear at the input.</li><li><strong>Server runtime:</strong> Play starts JavaScript, transpiled TypeScript or Blocks JS on the HA server. Stop and restart are available in the editor. Runtime status and logs remain available across browsers. The separate <strong>test run</strong> uses simulated states and events. HA YAML scripts and automations can be exported and run in Home Assistant after import.</li></ul><p><strong>Configure the live runtime</strong></p><p>Under <strong>Settings → Apps → HA Logic Studio Pro → Configuration</strong>, add the required entries, save and restart the app. The lists start empty. Example for a dedicated test helper:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_read_entities</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_write_entities</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">input_boolean.logic_studio_runtime_test</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">logic_studio_runtime_test</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Write access also allows reads. <code>ha.readState</code> and <code>ha.readAttribute</code> return the latest values confirmed by HA. <code>ha.onState</code>, <code>ha.onAttribute</code> and <code>ha.onEvent</code> respond to authorized changes and events. <code>ha.callAction</code> supports switching, setting number, text and select helpers, and pressing buttons on a single authorized target. <code>ha.schedule</code> handles time patterns and fixed times with optional weekdays in the HA time zone.</p><p>Scripts need to be started again after an app restart. On connection loss or a rejected action, the runtime stops the script and logs the error. Astronomical triggers and automatic reconnection are pending.</p><p><strong>Verified on the PC (64) test system with HA 2026.11.1:</strong> The runtime read a helper state and attribute, turned the helper on with a schedule and turned it off in response to a real HA event. Both state changes were reported. An imported Blocks JS schedule ran every two seconds. Earlier tests verified start, stop, restart and continued execution after leaving Studio with JavaScript and TypeScript.</p><p><strong>Control scripts and automations</strong></p><p>Under <strong>Blocks JS → System</strong>, use <strong>Select script or automation</strong> to choose a Home Assistant entity and connect the block to <strong>Control</strong>. You can start or stop scripts and enable, disable, or trigger automations once. <strong>Check conditions</strong> is enabled by default when triggering an automation. Turn it off to skip the conditions. For live execution, allow the target entity in <code>runtime_write_entities</code>.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.58" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.58 · GitHub and ZIP</a></p><p><strong>Functions and ioBroker import</strong></p><p><strong>Blocks JS → Functions</strong> offers two JavaScript function blocks, one with a return value and one without. Use the gear icon to set parameters and <strong>…</strong> to edit the code. After you add a definition, its call block appears in the palette.</p><p>ioBroker import preserves definitions, calls, parameters, and JavaScript code. Adapt ioBroker-specific API calls to the HA runtime and explicitly map imported object IDs to HA entities.</p><p><strong>Query history</strong></p><p>Use <strong>Blocks JS → Sendto → Query history</strong> to read states recorded by HA Recorder. If you omit the time range, the query uses the current day in the HA time zone. The result block returns timestamped values. ioBroker import preserves the time range, aggregation, interval, and count.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.57" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.57 · GitHub and ZIP</a></p></details><h3 id="ha-logic-studio-pro-0-1-21–0-1-40" tabindex="-1">HA Logic Studio Pro 0.1.21–0.1.40 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-21–0-1-40" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.21–0.1.40&quot;">​</a></h3><details class="details custom-block"><summary>Release history</summary><p><strong>0.1.29 · Manual saving and block editors</strong></p><p>All editors save changes through <strong>Save</strong>. <strong>Cancel</strong> restores the last saved version or discards a new project. Unsaved changes disable <strong>Play</strong> and <strong>Restart</strong>. Running scripts can still be stopped. Blocks A opens the entity picker directly from the block field. Blocks JS has an ioBroker-inspired palette with HA entities, actions and triggers, without Jinja.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.29" target="_blank" rel="noreferrer">Test update and ZIP</a></p><p><strong>0.1.28 · Editor translations</strong></p><p>Version <strong>0.1.28</strong> adds translations for Rules, Blocks A, Blocks JS, JavaScript, TypeScript and HA YAML. The language setting also applies to the function block diagram. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.28" target="_blank" rel="noreferrer">Test update and ZIP</a></p><p>Browser tests on the PC (64) test system covered the toolbars for function block diagrams, Rules, Blocks A, Blocks JS, JavaScript, TypeScript, HA automations and HA scripts in all three languages. The French code example dialog was also checked.</p><p>To install the Pro app, select <strong>HA Logic Studio Pro</strong> in the shared UGSo repository in the app store. For an existing GitHub installation, check for updates and select <strong>HA Logic Studio Pro → Update</strong>. Use <strong>DE</strong>, <strong>EN</strong> or <strong>FR</strong> at the top of the project pane to switch the editor language.</p><p><strong>0.1.26 · FBD Runtime</strong></p><p>Use <strong>Play</strong> to run a function block diagram on the HA server. <strong>Automatic</strong> responds to changes in authorized states and attributes; <strong>Fixed cycle</strong> evaluates the diagram every 100 to 60,000 ms. Simulation and YAML export are separate. <strong>Save</strong> commits the draft; <strong>Cancel</strong> restores the last saved version. The toolbar is available in DE/EN/FR.</p><p>On the PC (64) test system, starting in automatic mode turned the test helper on, and the 200 ms cycle turned it off again. Stop and discarding an unsaved change were also verified. Both modes were additionally tested locally with input changes.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.26" target="_blank" rel="noreferrer">GitHub test update and ZIP</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_logic_studio_pro" target="_blank" rel="noreferrer">App in the shared repository</a></p></details><h3 id="ha-logic-studio-pro-0-1-1–0-1-20" tabindex="-1">HA Logic Studio Pro 0.1.1–0.1.20 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-1–0-1-20" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.1–0.1.20&quot;">​</a></h3><details class="details custom-block"><summary>Release history</summary><p>The first public test releases introduced the standalone app with function block diagrams, Home Assistant import and React Flow.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases?q=ha-logic-studio-pro+0.1.&amp;expanded=true" target="_blank" rel="noreferrer">HA Logic Studio Pro · GitHub</a></p></details><h2 id="test-installation-from-github" tabindex="-1">Test installation from GitHub <a class="header-anchor" href="#test-installation-from-github" aria-label="Permalink to &quot;Test installation from GitHub&quot;">​</a></h2><p><a href="https://my.home-assistant.io/redirect/supervisor_add_addon_repository/?repository_url=https%3A%2F%2Fgithub.com%2Frockbaer2007%2Fugso-ha-mqtt-addons" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/supervisor_add_addon_repository.svg" alt="Add repository to Home Assistant"></a></p><ol><li>Under <strong>Settings → Apps → App store → Repositories</strong>, add the URL below. If “UGSo HA Apps” is already configured, check for updates instead.</li><li>Select and install <strong>UGSo Logic Studio</strong>. Enable advanced mode in your HA profile if experimental apps are hidden.</li><li>Start it and open its web UI. Supports <strong>HA OS/Supervised</strong>, <strong>amd64 and aarch64</strong>. The first container build may take several minutes. This is not a HACS/Marketplace frontend package.</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Keep an existing local test installation:</strong> GitHub and local apps have different repository IDs and separate data. Export your old plan using <strong>Projekt</strong> as JSON, then use <strong>Öffnen</strong> in the GitHub app. There is no automatic migration or uninstall. Each app retains its project and palette settings under <code>/data</code>.</p><p><strong>Update an existing GitHub app:</strong> Back up first, check for updates in the app manager and choose <strong>UGSo Logic Studio → Update</strong>. Keep the app installed: <code>/data</code>, entity IDs and existing plans are preserved. Do not uninstall or switch app IDs. On the PC (64) test system, the original plan, favorites, recent blocks and collapsed categories remained intact after the update.</p><h2 id="language-toolbar-and-documentation" tabindex="-1">Language, toolbar and documentation <a class="header-anchor" href="#language-toolbar-and-documentation" aria-label="Permalink to &quot;Language, toolbar and documentation&quot;">​</a></h2><p>Choose <strong>Language → Deutsch / English / Français</strong> in the header. Menus, block descriptions, entity picker and import/export dialogs switch without reloading. The choice is saved with browser/app preferences. <strong>Custom names, entity IDs, values, port names and generated YAML/JavaScript code are not translated.</strong></p><p><strong>Documentation</strong> on the right lists implemented keyboard shortcuts and, when a block is selected, its description and input/output ports. <strong>Ctrl+Z / Ctrl+Y</strong>: undo/redo; <strong>Delete</strong>: delete selection; <strong>Esc</strong>: cancel a connection/close a menu. Use Tab and Enter/Space to select and connect ports. Debugger commands from the ioBroker reference editor are not presented as implemented features.</p><p>The toolbar groups <strong>Undo/redo → Project → Simulation → Output</strong>. The three simulation buttons have equal dimensions and separate borders. The project menu also offers <strong>New project</strong> and <strong>Load example</strong>. Open entity selection using the icon <strong>beside HA entity ID</strong> in STATE_IN/STATE_OUT properties; the previous top entity button is removed.</p><p><img src="`+r+'" alt="German documentation view on the PC (64) test system with the original plan intact"></p><p><img src="'+a+'" alt="English documentation view of the same plan on the PC (64) test system"></p><p><img src="'+n+'" alt="French documentation view of the same plan on the PC (64) test system"></p><h2 id="two-kinds-of-plan" tabindex="-1">Two kinds of plan <a class="header-anchor" href="#two-kinds-of-plan" aria-label="Permalink to &quot;Two kinds of plan&quot;">​</a></h2><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Plan</th><th>Purpose and output</th></tr></thead><tbody><tr><td>Dataflow</td><td>Typed inputs/outputs, logic, math, selection, latches, edges, timers and counters. 33 implemented types; other reference types are marked templates. Export HA automation YAML, HA script YAML or a JavaScript function with a host interface.</td></tr><tr><td>Native HA flow</td><td>Import automations, scripts and blueprints as nested blocks. 53 additional HA types cover triggers, conditions, branches, loops, waits, variables and blueprint inputs. Export native HA YAML only.</td></tr></tbody></table></div><p>Dataflow simulation uses demo/snapshot values. Persistent blocks need the documented HA text helpers or a JavaScript memory host. Native HA flows are neither executed in the editor nor automatically translated to JavaScript. The JavaScript output is not an ioBroker script.</p><h2 id="drag-connections-and-overview" tabindex="-1">Drag connections and overview <a class="header-anchor" href="#drag-connections-and-overview" aria-label="Permalink to &quot;Drag connections and overview&quot;">​</a></h2><p>Hold the mouse button on a colored pin, drag to a matching opposite pin and release. The cursor becomes a crosshair and a wire preview follows the mouse. Compatible targets are highlighted green; incompatible or occupied inputs are marked red. Dragging from an input back to an output also works. <strong>Esc</strong> or releasing on empty canvas cancels; <strong>Undo</strong> removes a newly created wire.</p><p><strong>BOOL connects only to BOOL.</strong> Identical signal types are compatible, with additional <code>INT → REAL</code> widening. Explicit <code>ANY</code> pins are universal. Numbers and text are not silently converted to BOOL. Each input accepts exactly one wire; incompatible types, matching pin directions, self-connections and cycles are rejected with an explanation. For keyboard operation, select the output with Tab/Enter, then select the input and press Enter.</p><p><img src="'+i+'" alt="Compatible BOOL pins connected by mouse on the PC (64) test system"></p><p><img src="'+d+'" alt="STRING to BOOL is rejected with a clear type error"></p><p>The bottom-right <strong>MiniMap</strong> shows colored block positions and the visible viewport. Drag inside it to navigate and use the wheel to zoom. Drag empty canvas to pan; <strong>+/−</strong> change the zoom and <strong>Alles anzeigen</strong> fits all blocks. Drag a block by its header. The <strong>React Flow</strong> attribution remains visible at the bottom right. Since 0.1.8 the library actually runs in the editor; domain logic, type validation and exporters remain independent Logic Studio components.</p><p><img src="'+p+'" alt="React Flow canvas with preserved original plan and MiniMap on the PC (64) test system"></p><p><img src="'+c+'" alt="Local React Flow test with typed blocks"></p><p>The following images additionally document the earlier 0.1.7 tests.</p><p><img src="'+l+'" alt="Overview with block positions and visible viewport on the PC (64) test system"></p><h2 id="import-and-editing" tabindex="-1">Import and editing <a class="header-anchor" href="#import-and-editing" aria-label="Permalink to &quot;Import and editing&quot;">​</a></h2><p>Open <strong>HA importieren</strong>, choose automations/scripts/blueprints, and use <strong>Aus HA einlesen</strong>, a YAML/JSON file or pasted text. Select an entry, review its preview, then choose <strong>Import übernehmen</strong>. Save your existing plan as JSON first; project and source-file backups are also created.</p><p>The HA configuration mount is <strong>read-only</strong>. The app reads <code>automations.yaml</code>, <code>scripts.yaml</code> and blueprint files. Before parsing, sources are copied to <code>/data/ha-source-backups/&lt;timestamp&gt;/</code> using their original names. <code>secrets.yaml</code> is not opened; <code>!secret</code> and <code>!include</code> remain unresolved. Import referenced include files manually.</p><p>Orange <strong>FLOW</strong> wires represent execution order and branches: branch output → <strong>DO</strong>, then <strong>NEXT → DO</strong>. Yellow <strong>VALUE/REF</strong> wires show blueprint parameters and their <code>!input</code> usage. Properties contain HA configuration and branch paths as JSON. Parameter/field keys must be unique. Unknown sections remain <strong>YAML_ORIGINAL</strong>; missing wires can block export.</p><p><img src="'+h+'" alt="Import preview of existing HA blueprints"></p><p>Each block’s <strong>⋮ menu</strong> offers <strong>Eigenschaften</strong> (properties), <strong>Duplizieren</strong> (duplicate) and <strong>Löschen</strong> (delete). Duplication copies properties without wires. Deletion removes associated wires; undo restores them. Search, favorites and recently used blocks help navigation.</p><p><img src="'+g+'" alt="Per-block three-dot menu"></p><h2 id="validation-and-limits" tabindex="-1">Validation and limits <a class="header-anchor" href="#validation-and-limits" aria-label="Permalink to &quot;Validation and limits&quot;">​</a></h2><p><strong>0.1.12 on the PC (64) test system / HA Core 2026.10.4:</strong> Updated the local app from 0.1.8 after a full backup. DE/EN/FR, documentation and real HA entity selection passed. French survived browser reload, app restart and loading the saved app project again; German was restored afterwards. Project JSON differs <strong>only in version</strong>: all five blocks, three connections, names, values and positions are identical. Generated YAML is identical in EN and FR. No devices controlled. <strong>31 Node and nine Python tests</strong> passed. Older reports below remain as history.</p><p><img src="'+u+'" alt="German restored after the successful app restart on the PC (64) test system"></p><p><strong>0.1.8 on the PC (64) test system / HA Core 2026.10.4:</strong> Updated the existing local app after a full backup. Typed mouse connections, STRING→BOOL rejection, occupied inputs, move/undo, duplicate, zoom and MiniMap passed. The entity picker reads HA entities; a nested script with If/Then/Else, Delay and Stop was imported and exported with its structure preserved. The original plan was restored and compared after reload: <strong>all IDs, positions, parameters and three wires unchanged</strong>, along with favorites, recent blocks and collapsed categories. No devices were controlled. Docker build and container HTTP smoke test passed, as did <strong>29 Node and eight Python tests</strong>. Screenshots show the German UI. Light/dark switching was not manually retested in this step.</p><p>The <strong>0.1.5</strong> functional baseline was tested on <strong>PC (64) test system / HA Core 2026.10.4</strong>: actual blueprint import, automation/script/blueprint fixtures, semantically identical YAML exports and menu actions. <strong>0.1.6</strong> is its first public packaging. 22 Node and eight Python tests cover export, persistence, nested flows and safe source import; GitHub checks also build the container.</p><p><strong>0.1.7 on the PC (64) test system / HA Core 2026.10.4:</strong> Real mouse-drag tests passed for BOOL → BOOL and the reverse direction. STRING → BOOL and an occupied input were rejected. Overview, click navigation and Home were verified. The original plan was restored and compared with its backup: <strong>five blocks, three wires and all palette preferences preserved</strong>, including after the local update to 0.1.7. Full HA and separate plan/settings backups were created first; no devices were controlled. <strong>26 Node and eight Python tests</strong> currently pass. Screenshots show the German UI.</p><p>The editor does not provide complete HA semantic validation: verify targets, templates and selectors in HA. Comments, YAML anchors and formatting are not reconstructed. Import limits: <strong>1 MB, 200 blocks, 500 wires</strong>, bounded nesting and up to 250 blueprint files in standard folders. Controllers, calendar and custom subplans partly remain templates.</p><p>For local tests, extract the entire release ZIP, install Python 3.10+ and <code>requirements.txt</code>, then run <strong>Start-Demo.cmd</strong> on Windows. <code>http://127.0.0.1:4180/</code> shows demo entities without connecting to HA. The ZIP also contains <code>addon/logic_studio/</code> for local app installations.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/issues" target="_blank" rel="noreferrer">Report issues on GitHub</a> with versions, architecture and a minimal anonymized example. Do not publish credentials, personal automations or full backups. Further guides and the test report are included. MIT license; extracted block metadata attribution is in <code>THIRD-PARTY.txt</code>.</p>',75)])])}const C=m(v,[["render",y]]);export{x as __pageData,C as default};
